        require(address(this).balance >= amount);
        require(c.initialized() == false);
        bool r1;
        try c.sellDrugs() { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.collectDrugs(address(this)) { r2 = false; } catch { r2 = true; }
