        require(amount > 0);
        require(address(this).balance >= amount);
        c.seedMarket(drugs);
        uint256 expected = c.calculateDrugBuySimple(amount);
        expected = expected - c.devFee(expected);
        c.buyDrugs{value: amount}();
        assert(c.claimedDrugs(address(this)) == expected);
    }
    receive() external payable {}
}

